/**
 * Design tokens: the single source for interface color, size, depth, and
 * timing (docs/CODE-PRACTICES.md §5.2). Kit CSS reads these through custom
 * properties generated by `installTokenCss`, so variants and sizes are data
 * here rather than hand-written selectors elsewhere.
 *
 * Palette: blue plus greys and black only.
 */
export const COLOR = {
  black: "#05070a",
  ink: "#0b0e14",
  coal: "#121620",
  slate: "#1c222e",
  steel: "#2d3544",
  iron: "#4a5466",
  fog: "#8a94a6",
  mist: "#c5ccd8",
  paper: "#eceff4",
  white: "#ffffff",
  blue: "#2a6dff",
  blueHi: "#6b9bff",
  blueDeep: "#1440b0",
  blueNight: "#0b1f57",
} as const;

export interface VariantTokens {
  /** Surface color. */
  face: string;
  /** Depth edge and outline color. */
  edge: string;
  /** Text and icon color. */
  ink: string;
  /** Highlight used by hover, focus, and flash. */
  glow: string;
}

export const VARIANTS = {
  primary: {
    face: COLOR.blue,
    edge: COLOR.blueDeep,
    ink: COLOR.white,
    glow: COLOR.blueHi,
  },
  secondary: {
    face: COLOR.paper,
    edge: COLOR.fog,
    ink: COLOR.ink,
    glow: COLOR.white,
  },
  dark: {
    face: COLOR.slate,
    edge: COLOR.black,
    ink: COLOR.paper,
    glow: COLOR.steel,
  },
  glass: {
    face: "rgba(12, 15, 22, 0.78)",
    edge: "rgba(0, 0, 0, 0.55)",
    ink: COLOR.paper,
    glow: COLOR.steel,
  },
  quiet: {
    face: "transparent",
    edge: "transparent",
    ink: COLOR.paper,
    glow: COLOR.steel,
  },
  selected: {
    face: COLOR.white,
    edge: COLOR.blue,
    ink: COLOR.blueDeep,
    glow: COLOR.blueHi,
  },
  danger: {
    face: COLOR.black,
    edge: "#000000",
    ink: COLOR.white,
    glow: COLOR.iron,
  },
} satisfies Record<string, VariantTokens>;
export type VariantName = keyof typeof VARIANTS;

export interface SizeTokens {
  /** Minimum control height (px). Never below the 44 px touch target. */
  h: number;
  /** Label font size (px). */
  fs: number;
  /** Horizontal padding (px). */
  px: number;
  /** Corner radius (px). */
  r: number;
  /** Depth edge thickness (px); collapses when pressed. */
  depth: number;
}

export const SIZES = {
  sm: { h: 44, fs: 15, px: 14, r: 12, depth: 4 },
  md: { h: 52, fs: 18, px: 18, r: 14, depth: 5 },
  lg: { h: 62, fs: 22, px: 22, r: 16, depth: 6 },
  hero: { h: 74, fs: 30, px: 28, r: 18, depth: 7 },
  /** Full-screen announcements: countdown, GO!, GOAL!. */
  mega: { h: 120, fs: 72, px: 36, r: 26, depth: 8 },
} satisfies Record<string, SizeTokens>;
export type SizeName = keyof typeof SIZES;

export type UiCue =
  | "ui_tap"
  | "ui_press"
  | "ui_thump"
  | "ui_confirm"
  | "ui_deny"
  | "ui_tick"
  | "ui_toggle"
  | "ui_ready"
  | "ui_pop"
  | "ui_count";

export interface FeedbackProfile {
  /** Scale while held down. */
  pressScale: number;
  /** Fraction of the size's depth the control sinks while held. */
  pressDepth: number;
  /** Spring-back duration (ms). */
  releaseMs: number;
  /** Peak scale during spring-back. */
  overshoot: number;
  /** Sound played on press, or null for silent controls. */
  cue: UiCue | null;
  /** Vibration on press (ms), 0 for none. */
  haptic: number;
}

export const PROFILES = {
  soft: {
    pressScale: 0.97,
    pressDepth: 0.6,
    releaseMs: 170,
    overshoot: 1.025,
    cue: "ui_tap",
    haptic: 0,
  },
  punchy: {
    pressScale: 0.94,
    pressDepth: 1,
    releaseMs: 210,
    overshoot: 1.05,
    cue: "ui_press",
    haptic: 8,
  },
  heavy: {
    pressScale: 0.91,
    pressDepth: 1,
    releaseMs: 250,
    overshoot: 1.07,
    cue: "ui_thump",
    haptic: 14,
  },
  stick: {
    pressScale: 0.92,
    pressDepth: 0,
    releaseMs: 160,
    overshoot: 1.04,
    cue: null,
    haptic: 6,
  },
} satisfies Record<string, FeedbackProfile>;
export type ProfileName = keyof typeof PROFILES;

export const MOTION = {
  fast: 100,
  base: 160,
  slow: 240,
  spring: "cubic-bezier(.3, 1.6, .5, 1)",
  out: "cubic-bezier(.2, .8, .2, 1)",
} as const;

let installed = false;

/**
 * Write variant and size tokens as attribute-scoped custom properties, once.
 * Every kit element carries `data-variant` and `data-size`; ui.css only reads
 * the resulting `--face`, `--edge`, `--ink`, `--glow`, `--h`, `--fs`, `--px`,
 * `--r`, and `--depth` properties.
 */
export function installTokenCss() {
  if (installed || typeof document === "undefined") return;
  installed = true;
  const rules: string[] = [
    `:root{${Object.entries(COLOR)
      .map(([k, v]) => `--c-${k}:${v};`)
      .join("")}--spring:${MOTION.spring};--out:${MOTION.out};--t-fast:${MOTION.fast}ms;--t-base:${MOTION.base}ms;--t-slow:${MOTION.slow}ms;}`,
  ];
  for (const [name, v] of Object.entries(VARIANTS))
    rules.push(
      `[data-variant="${name}"]{--face:${v.face};--edge:${v.edge};--ink:${v.ink};--glow:${v.glow};}`,
    );
  for (const [name, s] of Object.entries(SIZES))
    rules.push(
      `[data-size="${name}"]{--h:${s.h}px;--fs:${s.fs}px;--px:${s.px}px;--r:${s.r}px;--depth:${s.depth}px;}`,
    );
  for (const [name, p] of Object.entries(PROFILES))
    rules.push(
      `[data-profile="${name}"]{--press-scale:${p.pressScale};--press-depth:${p.pressDepth};}`,
    );
  const style = document.createElement("style");
  style.dataset.tokens = "";
  style.textContent = rules.join("\n");
  document.head.prepend(style);
}
